// --- building blocks --------------------------------------------------------

type Cat =
  | "heritage_site" | "museum" | "gallery" | "temple" | "church" | "mosque"
  | "market" | "street_food" | "restaurant" | "cafe" | "craft_workshop"
  | "art_studio" | "music_live" | "dance_performance" | "theatre"
  | "nature" | "beach" | "nightlife" | "shopping" | "community_hosted"
  | "hidden_place" | "wellness" | "adventure" | "festival" | "event";

interface Seed {
  id: string;
  name: string;
  category: Cat;
  lat: number;
  lon: number;
  hood: string;
  /** Estimated minutes on site. Inferred. */
  dur: number;
  /** Estimated rupees per person. Inferred. 0 = free. */
  price: number;
  cap: number | null;
  hours: string | null;
  stepFree: boolean | null;
  stroller: boolean | null;
  restroom: boolean | null;
  kid: boolean | null;
  indoor: "indoor" | "outdoor" | "covered" | "mixed";
  weather: "none" | "rain" | "heat" | "wind" | "any";
  blurb: string;
  desc: string;
  kw: string[];
  rating: number;
  count: number;
  best: Array<"early_morning" | "morning" | "afternoon" | "evening" | "night">;
  atmos: string[];
  acts: string[];
  land: string[];
  book?: { required: boolean; leadTimeMin: number; walkIn: boolean };
  /** How confident we are this is worth a traveller's time. */
  signal?: number;
}

