// --- emit --------------------------------------------------------------------

const rand = seededRandom(seedFrom("mumbai", "seed", SEEDS.length));

interface Emitted {
  id: string;
  name: string;
  category: string;
  location: { lat: number; lon: number };
  durationMin: number;
  pricePerPerson: { minor: number; currency: string } | null;
  capacity: number | null;
  hours: { raw: string | null; status: string; lastVerified: string | null };
  indoorOutdoor: string;
  accessibility: Record<string, boolean | null>;
  kidFriendly: boolean | null;
  minAge: number | null;
  diets: string[];
  cuisines: string[];
  rating: { value: number; count: number; rawMean: number | null };
  blurb: string | null;
  description: string | null;
  keywords: string[];
  perception: { landscape: string[]; activities: string[]; atmosphere: string[] };
  bestTimeOfDay: string[];
  requiresJourney: boolean;
  booking: { required: boolean; leadTimeMin: number; walkIn: boolean };
  bestMonths: number[];
  weatherSensitive: string;
  provenance: Record<string, string>;
  providerId: string | null;
  neighbourhood: string;
  city: string;
}

  function toRow(s: Seed, _index: number): Emitted {
  // A little rating jitter so the Bayesian smoothing is exercised rather than
  // fed perfectly round numbers. Deterministic, so re-runs are identical.
  const jitter = Math.round((rand() - 0.5) * 12) / 100;
  const rawMean = Math.max(1, Math.min(5, Number((s.rating + jitter).toFixed(2))));

  const categories: Record<string, string[]> = {
    street_food: ["north indian", "chaat", "mughlai"],
    restaurant: ["north indian", "mughlai", "parsī", "iranian"],
    cafe: ["cafe", "italian", "continental"],
    market: ["vegetarian", "north indian"],
    temple: ["vegetarian"],
    mosque: ["vegetarian"],
  };

  const inferred: Record<string, string> = {
    durationMin: "inferred",
    pricePerPerson: "inferred",
    capacity: "inferred",
    kidFriendly: "inferred",
  };
  const curated: Record<string, string> = {
    name: "curated",
    category: "curated",
    location: "curated",
    hours: "curated",
    neighbourhood: "curated",
    blurb: "curated",
    description: "curated",
  };

  return {
    id: s.id,
    name: s.name,
    category: s.category,
    location: { lat: s.lat, lon: s.lon },
    durationMin: s.dur,
    pricePerPerson: s.price === 0 ? null : { minor: s.price * 100, currency: "INR" },
    capacity: s.cap,
    hours: { raw: s.hours, status: s.hours ? "ok" : "absent", lastVerified: null },
    indoorOutdoor: s.indoor,
    accessibility: {
      stepFree: s.stepFree,
      strollerOk: s.stroller,
      lowStairs: null,
      hearingLoop: null,
      seatingAvailable: null,
      restroomOnSite: s.restroom,
    },
    kidFriendly: s.kid,
    minAge: null,
    diets: s.category === "temple" || s.category === "mosque" ? ["vegetarian"] : [],
    cuisines: categories[s.category] ?? [],
    rating: { value: rawMean, count: s.count, rawMean },
    blurb: s.blurb,
    description: s.desc,
    keywords: s.kw,
    perception: { landscape: s.land, activities: s.acts, atmosphere: s.atmos },
    bestTimeOfDay: s.best,
    requiresJourney: s.category === "heritage_site" || s.category === "adventure",
    booking: s.book ?? { required: false, leadTimeMin: 0, walkIn: true },
    bestMonths: [],
    weatherSensitive: s.weather,
    provenance: { ...curated, ...inferred },
    providerId: null,
    neighbourhood: s.hood,
    city: "Mumbai",
  };
}

const rows = SEEDS.map(toRow);

mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(OUT, rows.map((r) => JSON.stringify(r)).join("\n") + "\n", "utf8");

const byHood = new Map<string, number>();
for (const r of rows) byHood.set(r.neighbourhood, (byHood.get(r.neighbourhood) ?? 0) + 1);

console.log(`wrote ${rows.length} records -> ${OUT.replace(process.cwd() + "/", "")}`);
console.log(`neighbourhoods: ${byHood.size}`);
console.log(`with inferred duration: ${rows.filter((r) => r.provenance.durationMin === "inferred").length}`);
console.log(`free: ${rows.filter((r) => r.pricePerPerson === null).length}`);
console.log(`hours listed: ${rows.filter((r) => r.hours.raw !== null).length}`);
if (!existsSync(OUT)) process.exit(1);
